.ap-tabela{width:100%;border-collapse:collapse;font-size:.92rem}
.ap-tabela th{text-align:left;font-size:.7rem;text-transform:uppercase;letter-spacing:.04em;
  color:var(--ap-suave);padding:8px 10px;border-bottom:2px solid var(--ap-borda)}
.ap-tabela td{padding:11px 10px;border-bottom:1px solid var(--ap-borda);vertical-align:middle}
.ap-tabela tr:nth-child(even) td{background:var(--ap-alt)}
.ap-uf-sigla{font-weight:800;color:var(--ap-verde)}
.ap-tabela .ap-lid{font-weight:700}
.ap-mini{font-size:.76rem;color:var(--ap-suave)}
.ap-rolagem{overflow-x:auto}
.ap-fonte{font-size:.8rem;color:var(--ap-suave);margin-top:20px;line-height:1.5}
.ap-aviso{padding:26px;border:2px dashed var(--ap-borda);border-radius:14px;text-align:center;
  color:var(--ap-suave);line-height:1.6}
.ap-aviso b{display:block;font-size:1.15rem;color:var(--ap-texto);margin-bottom:6px}
.ap-mais{margin-top:14px;text-align:center}
.ap-mais button{background:none;border:1px solid var(--ap-borda);border-radius:8px;padding:9px 20px;
  font-weight:700;cursor:pointer;color:var(--ap-texto);font-size:.88rem;font-family:inherit}
html[data-theme="dark"] #hmt-apuracao,body.dark-mode #hmt-apuracao,html[data-theme="dark"] #ap-ficha,body.dark-mode #ap-ficha{
  --ap-fundo:#161b18;--ap-borda:#2b332e;--ap-texto:#eef3f0;--ap-suave:#9fb0a6;--ap-alt:#1c2320}
@media (prefers-color-scheme:dark){html:not([data-theme="light"]) #hmt-apuracao,html:not([data-theme="light"]) #ap-ficha{
  --ap-fundo:#161b18;--ap-borda:#2b332e;--ap-texto:#eef3f0;--ap-suave:#9fb0a6;--ap-alt:#1c2320}}
@media (max-width:600px){
  .ap-destaque{grid-template-columns:1fr}
  .ap-cand{grid-template-columns:40px 1fr;row-gap:6px}
  .ap-cand .ap-av{width:40px;height:40px}
  .ap-dcard .ap-av{width:68px;height:68px}
  .ap-votos{grid-column:1/-1;text-align:left;display:flex;align-items:baseline;gap:10px}
  .ap-filtros{width:100%}.ap-filtros label{flex:1 1 45%}.ap-filtros select{min-width:0;width:100%}
}
</style>

<script>
(function () {
  // ?demo=1 abre a demonstração com os resultados oficiais de 2022
  var DEMO = /[?&]demo=1/.test(location.search);
  var BASE = "/content/media/apuracao/" + (DEMO ? "demo/" : "");
  var UFS = {br:"Brasil",ac:"Acre",al:"Alagoas",am:"Amazonas",ap:"Amapá",ba:"Bahia",ce:"Ceará",
    df:"Distrito Federal",es:"Espírito Santo",go:"Goiás",ma:"Maranhão",mg:"Minas Gerais",
    ms:"Mato Grosso do Sul",mt:"Mato Grosso",pa:"Pará",pb:"Paraíba",pe:"Pernambuco",pi:"Piauí",
    pr:"Paraná",rj:"Rio de Janeiro",rn:"Rio Grande do Norte",ro:"Rondônia",rr:"Roraima",
    rs:"Rio Grande do Sul",sc:"Santa Catarina",se:"Sergipe",sp:"São Paulo",to:"Tocantins",zz:"Exterior"};
  var indice = null, mostrarTodos = false, aba = "resultado", muniCache = {};
  var ultimo = null, partido = "";   // último resultado carregado e filtro de partido
  var pedido = 0, ultimoCargo = "", ligado = false, pedidoEleitos = 0;
  var ordem = "votos";   // ordem dentro do filtro de partido: votos | nome | numero
  var $ = function (id) { return document.getElementById(id); };
  var pega = function (u) {
    return fetch(BASE + u + "?t=" + Date.now())
      .then(function (r) { return r.ok ? r.json() : null; }).catch(function () { return null; });
  };
  function esc(v) {
    return String(v == null ? "" : v).replace(/[&<>"']/g, function (ch) {
      return {"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"}[ch];
    });
  }
  function siglaDe(c) { return c.sg || String(c.cc || "").split(" - ")[0].trim(); }
  function proporcional() { return /^000[678]$/.test(ultimoCargo || $("ap-cargo").value); }
  function num(v) { var n = parseInt(v, 10); return isNaN(n) ? "—" : n.toLocaleString("pt-BR"); }
  function pctNum(v) { return parseFloat(String(v || "0").replace(",", ".")) || 0; }
  function eleito(c) { return c.e === "s" || /^eleito/i.test(c.st || ""); }
  function segundoTurno(c) { return /2.*turno/i.test(c.st || ""); }
  function selo(c) {
    if (eleito(c)) return '<span class="ap-tag">' + (c.mandato ? "Reeleito" : "Eleito") + "</span>";
    if (segundoTurno(c)) return '<span class="ap-tag segundo">2º turno</span>';
    if (c.dvt && /judice|anulad|indeferid|cassad/i.test(c.dvt)) return '<span class="ap-tag segundo">Sub judice</span>';
    return "";
  }
  function aviso(titulo, texto) {
    $("ap-lista").innerHTML = '<div class="ap-aviso"><b>' + titulo + "</b>" + texto + "</div>";
    $("ap-destaque").innerHTML = "";
    $("ap-progresso").hidden = true; $("ap-totais").hidden = true;
  }

  function trocarAba(nova) {
    aba = nova;
    Array.prototype.forEach.call(document.querySelectorAll(".ap-aba"), function (b) {
      b.classList.toggle("ativa", b.dataset.aba === nova);
    });
    $("ap-painel-resultado").hidden = nova !== "resultado";
    $("ap-painel-placar").hidden = nova !== "placar";
    $("ap-painel-gastos").hidden = nova !== "gastos";
    $("ap-painel-partidos").hidden = nova !== "partidos";
    $("ap-painel-eleitos").hidden = nova !== "eleitos";
    if (nova === "partidos") renderPartidos();
    if (nova === "eleitos") renderEleitos();
    if (nova === "placar") renderPlacar();
    if (nova === "gastos") renderGastos();
  }

  function filtrosPrevistos() {
    // fora da janela de apuração: seletores testáveis com os cargos e UFs
    // previstos da Eleição Geral (trocados pelos reais quando o TSE liberar)
    if ($("ap-cargo").options.length) return;
    var cargos = {"0001": "Presidente", "0003": "Governador",
                  "0005": "Senador", "0006": "Deputado Federal",
                  "0007": "Deputado Estadual", "0008": "Deputado Distrital"};
    $("ap-cargo").innerHTML = Object.keys(cargos).map(function (c) {
      return '<option value="' + c + '">' + cargos[c] + "</option>";
    }).join("");
    $("ap-cargo").value = "0003";
    $("ap-uf").innerHTML = Object.keys(UFS).map(function (u) {
      return '<option value="' + u + '">' + UFS[u] + "</option>";
    }).join("");
    $("ap-uf").value = "mt";
  }

  function montarFiltros() {
    var cargos = indice.disponivel || {}, codigos = Object.keys(cargos).sort();
    if (!codigos.length) return false;
    $("ap-cargo").innerHTML = codigos.map(function (c) {
      return '<option value="' + c + '">' + cargos[c].rotulo + "</option>";
    }).join("");
    $("ap-cargo").value = (cargos["0003"] && cargos["0003"].abr.indexOf("mt") > -1) ? "0003" : codigos[0];
    preencherUfs();
    return true;
  }

  function preencherUfs() {
    var abrs = (indice.disponivel[$("ap-cargo").value] || {}).abr || [];
    var anterior = $("ap-uf").value;
    $("ap-uf").innerHTML = abrs.map(function (u) {
      return '<option value="' + u + '">' + (UFS[u] || u.toUpperCase()) + "</option>";
    }).join("");
    if (abrs.indexOf(anterior) > -1) $("ap-uf").value = anterior;
    else if (abrs.indexOf("mt") > -1) $("ap-uf").value = "mt";
  }

  function preencherMunicipios() {
    var uf = $("ap-uf").value, cargo = $("ap-cargo").value, chave = uf + "-c" + cargo;
    var lb = $("ap-lb-mun");
    function aplicar(d) {
      if (!d || !d.municipios || !d.municipios.length) { lb.hidden = true; return atualizar(); }
      lb.hidden = false;
      var antes = $("ap-mun").value;      // trocar de cargo não perde a cidade escolhida
      $("ap-mun").innerHTML = '<option value="">Todo o estado</option>' +
        d.municipios.map(function (m) {
          return '<option value="' + m.cd + '">' + m.nm + (m.capital ? " (capital)" : "") + "</option>";
        }).join("");
      if (antes && d.municipios.some(function (m) { return m.cd === antes; })) $("ap-mun").value = antes;
      atualizar();
    }
    if (muniCache[chave] !== undefined) return aplicar(muniCache[chave]);
    pega("municipios-" + chave + ".json").then(function (d) {
      muniCache[chave] = d;
      if ($("ap-uf").value + "-c" + $("ap-cargo").value !== chave) return;   // resposta de uma seleção antiga
      aplicar(d);
    });
  }

  // foto oficial do TSE copiada para o nosso domínio; sem foto (ou se falhar), ficam as iniciais
  function avatar(c) {
    var ini = String(c.nm || "").split(/\s+/).filter(Boolean).slice(0, 2)
      .map(function (p) { return p.charAt(0); }).join("");
    return '<span class="ap-av" data-ini="' + ini + '" aria-hidden="true">' +
      (c.foto && /^\/content\/media\/apuracao\/fotos\/\d+\.jpeg$/.test(c.foto)
        ? '<img src="' + c.foto + '" alt="" loading="lazy" decoding="async" onerror="this.remove()">' : "") +
      "</span>";
  }

  function renderDestaque(cands) {
    if (cands.length < 2) { $("ap-destaque").innerHTML = ""; return; }
    $("ap-destaque").innerHTML = '<div class="ap-destaque">' + cands.slice(0, 2).map(function (c, i) {
      return '<div class="ap-dcard' + (i === 0 ? " lider" : "") + '"' + attrFicha(c) + ">" +
        '<div class="ap-dtopo">' + avatar(c) + '<div style="min-width:0">' +
        '<div class="ap-dnum">Nº ' + (c.n || "") + selo(c) + "</div>" +
        '<div class="ap-dnome">' + (c.nm || "") + "</div>" +
        '<div class="ap-dpart">' + esc(siglaDe(c)) + "</div></div></div>" +
        '<div class="ap-dpct">' + (c.pvap || "0") + "%</div>" +
        '<div class="ap-dvotos">' + num(c.vap) + " votos</div></div>";
    }).join("") + "</div>";
  }

  // ---------- partidos ----------
  function preencherPartidos(d) {
    var lb = $("ap-lb-par"), sel = $("ap-par"), visto = {}, lista = [];
    (d.agremiacoes || []).forEach(function (a) {
      (a.partidos || []).forEach(function (p) { if (p.sg && !visto[p.sg]) { visto[p.sg] = 1; lista.push(p.sg); } });
    });
    (d.candidatos || []).forEach(function (c) {
      var sg = siglaDe(c); if (sg && !visto[sg]) { visto[sg] = 1; lista.push(sg); }
    });
    $("ap-btn-partidos").hidden = !(d.agremiacoes && d.agremiacoes.length);
    if (lista.length < 2) { lb.hidden = true; partido = ""; return; }
    lista.sort(function (a, b) { return a.localeCompare(b, "pt-BR"); });
    var chave = lista.join("|");
    if (sel.dataset.chave !== chave) {          // só refaz se a lista mudou (não fecha o menu aberto)
      sel.innerHTML = '<option value="">Todos</option>' + lista.map(function (sg) {
        return '<option value="' + esc(sg) + '">' + esc(sg) + "</option>";
      }).join("");
      sel.dataset.chave = chave;
    }
    if (partido && !visto[partido]) partido = "";
    sel.value = partido;
    lb.hidden = false;
  }
  function achaPartido(d, sg) {
    var achou = null;
    (d.agremiacoes || []).forEach(function (a) {
      (a.partidos || []).forEach(function (p) { if (p.sg === sg) achou = {p: p, a: a}; });
    });
    return achou;
  }
  function resumoPartido(d, qtd) {
    var x = achaPartido(d, partido), vv = parseInt(d.votos_validos_c || d.votos_validos, 10) || 0;
    var p = x ? x.p : null, a = x ? x.a : null;
    var votos = p ? p.votos : (d.candidatos || []).filter(function (c) { return siglaDe(c) === partido; })
      .reduce(function (t, c) { return t + (parseInt(c.vap, 10) || 0); }, 0);
    var pct = vv ? (100 * votos / vv).toFixed(2).replace(".", ",") : "—";
    var grupo = a && a.partidos && a.partidos.length > 1;
    var cad = proporcional() && !d.municipio && a && a.vagas != null && d.vagas;
    return '<div class="ap-psum"><div><div class="ap-psg">' + esc(partido) + "</div>" +
      '<div class="ap-pinfo">' + esc(a ? a.nm : "") + (grupo ? " (" + esc(a.com) + ")" : "") + "</div></div>" +
      '<div><div class="ap-pnum">' + pct + '%</div><div class="ap-pinfo">' + num(votos) + " votos" +
      (p && p.legenda ? " · " + num(p.legenda) + " de legenda" : "") + "</div></div>" +
      (cad ? '<div><div class="ap-pnum">' + esc(a.vagas) + '</div><div class="ap-pinfo">' +
        (grupo ? "cadeiras da federação" : "cadeiras") + " de " + esc(d.vagas) + " (projeção)</div></div>" : "") +
      '<div class="ap-pinfo">' + qtd + (qtd === 1 ? " candidato" : " candidatos") + "</div></div>";
  }
  function escolhePartido(sg) {
    partido = sg; mostrarTodos = false;
    $("ap-par").value = sg;
    trocarAba("resultado");
    if (ultimo) render(ultimo, ultimo.municipio || "");
    var alvo = $("ap-painel-resultado");
    if (alvo && alvo.getBoundingClientRect().top < 0) alvo.scrollIntoView({block: "start"});
  }
  function renderPartidos() {
    var d = ultimo, el = $("ap-partidos");
    if (!d) return;
    var ags = d.agremiacoes || [];
    if (!ags.length) {
      el.innerHTML = '<div class="ap-aviso"><b>Sem resumo por partido</b>Esta seleção não traz votos por partido.</div>';
      return;
    }
    var cad = proporcional() && !d.municipio && d.vagas;
    var max = ags[0].votos || 1;
    el.innerHTML = '<p class="ap-ptopo">' + (cad
      ? "<b>" + esc(d.vagas) + "</b> cadeiras em disputa · quociente eleitoral de <b>" + num(d.quociente) +
        "</b> votos. As cadeiras são a projeção do TSE com " + esc(d.secoes_totalizadas_pct) +
        "% das seções apuradas e podem mudar até o fim da apuração."
      : "Votos por partido, federação ou coligação com " + esc(d.secoes_totalizadas_pct) + "% das seções apuradas" +
        (d.municipio ? " em " + esc(d.municipio) : "") + ".") + "</p>" +
      '<div class="ap-rolagem"><table class="ap-tabela ap-ptab"><thead><tr><th>Partido, federação ou coligação</th>' +
      "<th>Votos</th><th>% dos válidos</th>" + (cad ? "<th>Cadeiras</th>" : "") + "</tr></thead><tbody>" +
      ags.map(function (a) {
        var unico = (a.partidos || []).length === 1 ? a.partidos[0].sg : "";
        var isolado = unico && a.tp === "i";      // partido sozinho: a própria sigla é o botão de filtro
        var nome = isolado ? '<button type="button" class="ap-chip ap-chip-lid" data-sg="' + esc(unico) + '">' + esc(unico) +
            '</button><div class="ap-mini">' + esc(a.nm) + "</div>"
          : '<span class="ap-lid">' + esc(a.nm) + '</span><div class="ap-mini">' + esc(a.com) + "</div>";
        var chips = isolado ? "" : (a.partidos || []).map(function (p) {
          return '<button type="button" class="ap-chip" data-sg="' + esc(p.sg) + '">' + esc(p.sg) +
            ((a.partidos.length > 1) ? " · " + num(p.votos) : "") + "</button>";
        }).join("");
        return "<tr><td>" + nome + "<div>" + chips + "</div></td>" +
          "<td>" + num(a.votos) + (a.legenda ? '<div class="ap-mini">' + num(a.legenda) + " de legenda</div>" : "") + "</td>" +
          "<td><strong>" + esc(a.pct) + '%</strong><div class="ap-pbar"><span style="width:' +
          Math.max(1, Math.round(100 * (a.votos || 0) / max)) + '%"></span></div></td>' +
          (cad ? '<td><span class="ap-cad' + (parseInt(a.vagas, 10) ? "" : " zero") + '">' + esc(a.vagas || 0) + "</span></td>" : "") +
          "</tr>";
      }).join("") + "</tbody></table></div>";
    Array.prototype.forEach.call(el.querySelectorAll(".ap-chip"), function (b) {
      b.onclick = function () { escolhePartido(b.dataset.sg); };
    });
  }

  // ---------- eleitos ----------
  // proporcional, enquanto o TSE não totaliza: os mais votados de cada partido/federação dentro
  // das vagas que o próprio TSE projeta, com pelo menos 10% do quociente eleitoral
  function projetados(d, cargo) {
    var prop = cargo ? /^000[678]$/.test(cargo) : proporcional();
    if (!(prop && !d.municipio && d.vagas)) return [];
    var min = (parseInt(d.quociente, 10) || 0) * 0.1, sel = [];
    (d.agremiacoes || []).forEach(function (a) {
      var n = parseInt(a.vagas, 10) || 0;
      if (!n) return;
      sel = sel.concat((d.candidatos || []).filter(function (c) {
        return c.ag === a.nm && !c.dvt && (parseInt(c.vap, 10) || 0) >= min;
      }).slice(0, n));
    });
    return sel.sort(function (x, y) { return (parseInt(y.vap, 10) || 0) - (parseInt(x.vap, 10) || 0); });
  }
  function attrFicha(c, cargo, uf) {
    cargo = cargo || ultimoCargo || $("ap-cargo").value;
    uf = uf || $("ap-uf").value;
    return ' data-ficha="' + esc(cargo + "|" + uf + "|" + c.n) + '" tabindex="0" role="button" aria-label="Ver a ficha de ' +
      esc(c.nm || "") + '"';
  }
  function linhaCand(c, o) {
    o = o || {};
    return '<div class="ap-cand' + (eleito(c) ? " eleito" : "") + '" style="--pct:' + pctNum(c.pvap) + '%"' +
      attrFicha(c, o.cargo, o.uf) + ">" +
      avatar(c) +
      '<div style="min-width:0"><div class="ap-nome">' + esc(c.nm || "") + selo(c) +
      (o.proj && !eleito(c) ? ' <span class="ap-tag proj">Na projeção</span>' : "") +
      (o.tag && !eleito(c) ? ' <span class="ap-tag proj">' + esc(o.tag) + "</span>" : "") +
      (o.reel && !eleito(c) ? ' <span class="ap-tag reel">Reeleito</span>' : "") +
      (o.mandato && !eleito(c) ? ' <span class="ap-tag proj">Em mandato</span>' : "") + "</div>" +
      (c.nv ? '<div class="ap-part">Vice: ' + esc(c.nv) + "</div>" : "") +
      (c.sp ? '<div class="ap-part">Suplentes: ' + esc(c.sp) + "</div>" : "") +
      '<div class="ap-part">' + (o.pos ? '<span class="ap-pos">' + o.pos + "º no geral</span> · " : "") +
      "Nº " + esc(c.n || "") + " · " + esc(c.cc || "") + "</div></div>" +
      '<div class="ap-votos"><span class="ap-pct">' + esc(c.pvap || "0") + "%</span>" +
      '<span class="ap-abs">' + num(c.vap) + " votos</span></div></div>";
  }
  var CARGOS_ELEITOS = [["0001", "Presidente"], ["0003", "Governador"], ["0005", "Senado"],
    ["0006", "Deputados federais"], ["0007", "Deputados estaduais"], ["0008", "Deputados distritais"]];
  // situação de um cargo: oficial do TSE > definido matematicamente > projeção > liderança
  function eleitosDe(d, cargo) {
    var todos = d.candidatos || [], vagas = parseInt(d.vagas, 10) || 1, pct = d.secoes_totalizadas_pct;
    var of = todos.filter(eleito);
    if (of.length) return {rot: "resultado oficial do TSE", lista: of, tipo: "oficial"};
    var t2 = todos.filter(segundoTurno);
    if (t2.length) return {rot: "vão ao 2º turno · resultado oficial do TSE", lista: t2, tipo: "oficial"};
    if (/^000[678]$/.test(cargo) && d.vagas) {
      var pr = projetados(d, cargo);
      return {rot: "projeção: " + pr.length + " de " + d.vagas + " cadeiras com " + pct + "% apurado", lista: pr, tipo: "proj"};
    }
    if (d.definido === "e") return {rot: "matematicamente definido com " + pct + "% apurado", lista: todos.slice(0, vagas),
      tipo: "def", tag: "Matematicamente eleito"};
    if (d.definido === "s") return {rot: "2º turno matematicamente definido com " + pct + "% apurado", lista: todos.slice(0, 2),
      tipo: "t2", tag: "2º turno"};
    return {rot: "ainda não definido · " + pct + "% apurado", lista: todos.slice(0, vagas), tipo: "lid", tag: "Liderando"};
  }
  function secaoEleitos(d, cargo, rotulo) {
    var e = eleitosDe(d, cargo);
    if (!e.lista.length) return "";
    var reelege = e.tipo === "oficial" || e.tipo === "def" || e.tipo === "proj";
    var nRe = e.lista.filter(function (c) { return c.mandato && (reelege || eleito(c)); }).length;
    return '<section class="ap-esec"><h3>' + esc(rotulo) + " <small>" + esc(e.rot) +
      (nRe ? " · " + nRe + (nRe === 1 ? " reeleito" : " reeleitos") : "") + "</small></h3>" +
      '<div class="ap-lista">' + e.lista.map(function (c) {
        return linhaCand(c, {cargo: cargo, uf: cargo === "0001" ? "br" : $("ap-uf").value,
          proj: e.tipo === "proj", tag: e.tipo === "proj" ? "" : e.tag,
          reel: c.mandato && reelege, mandato: c.mandato && !reelege});
      }).join("") + "</div></section>";
  }
  function renderEleitos() {
    var el = $("ap-eleitos"), uf = $("ap-uf").value;
    if (!indice || !uf) return;
    var meu = ++pedidoEleitos, disp = indice.disponivel || {};
    var cargos = CARGOS_ELEITOS.filter(function (x) {
      var a = (disp[x[0]] || {}).abr || [];
      return x[0] === "0001" ? a.indexOf("br") > -1 : (uf !== "br" && a.indexOf(uf) > -1);
    });
    Promise.all(cargos.map(function (x) {
      return pega((x[0] === "0001" ? "br" : uf) + "-c" + x[0] + ".json");
    })).then(function (ds) {
      if (meu !== pedidoEleitos) return;          // trocou de estado no meio: descarta
