    "0007": "Deputado estadual", "0008": "Deputado distrital"};
  function geo(nome) {
    if (GEO[nome]) return Promise.resolve(GEO[nome]);
    return fetch("/content/media/apuracao/" + nome + ".json").then(function (r) { return r.ok ? r.json() : null; })
      .then(function (g) { if (g) GEO[nome] = g; return g; }).catch(function () { return null; });
  }
  function pctTxt(v, t) { return t ? (100 * v / t).toFixed(2).replace(".", ",") : "0,00"; }
  // escala de cor: do cinza-esverdeado (pouco voto) ao verde-escuro (muito voto), relativa ao máximo do candidato
  var ESCALA = ["#e7f3ec", "#bfe3cd", "#8dcfa8", "#55b67f", "#1f9a5a", "#0b6b3a"];
  function corDe(p, max) {
    if (!(p > 0)) return "var(--ap-alt)";
    var i = Math.min(ESCALA.length - 1, Math.floor(ESCALA.length * p / (max || 1)));
    return ESCALA[Math.max(0, i)];
  }
  function legenda(max) {
    return '<div class="ap-legenda">0%' + ESCALA.map(function (c) { return '<i style="background:' + c + '"></i>'; }).join("") +
      " " + max.toFixed(1).replace(".", ",") + "%</div>";
  }
  function barras(lista, fmt) {
    var max = Math.max.apply(null, lista.map(function (x) { return x.p; }).concat([0.0001]));
    return '<div class="ap-barras">' + lista.map(function (x) {
      return '<div class="ap-barra-l"><span class="ap-bn" title="' + esc(x.nm) + '">' + esc(x.nm) + "</span>" +
        '<span class="ap-bt"><span style="width:' + (100 * x.p / max).toFixed(1) + '%"></span></span>' +
        '<span class="ap-bv">' + (fmt ? fmt(x) : x.p.toFixed(2).replace(".", ",") + "%") + "</span></div>";
    }).join("") + "</div>";
  }
  function mapaSvg(g, chaveDe, itens, rotulo) {
    // itens: {chave: {p, v, nm, extra}}
    var max = 0;
    Object.keys(itens).forEach(function (k) { if (itens[k].p > max) max = itens[k].p; });
    var areas = g.mun || g.uf, paths = Object.keys(areas).map(function (k) {
      var a = areas[k], it = itens[chaveDe(k)];
      if (!a.d) return "";
      return '<path d="' + a.d + '" fill="' + corDe(it ? it.p : 0, max) + '" data-k="' + esc(chaveDe(k)) +
        '" data-nm="' + esc(a.nm) + '"><title>' + esc(a.nm) + (it ? " — " + it.p.toFixed(2).replace(".", ",") + "%" : "") +
        "</title></path>";
    }).join("");
    return '<div class="ap-mapa"><svg viewBox="0 0 ' + g.vb[0] + " " + g.vb[1] + '" role="img" aria-label="' + esc(rotulo) +
      '">' + paths + '</svg><div class="ap-mapa-dica" aria-live="polite">Toque numa área do mapa para ver os votos.</div>' +
      legenda(max) + "</div>";
  }
  function ligarMapa(el, itens, fmt) {
    var dica = el.querySelector(".ap-mapa-dica"), ativo = null;
    Array.prototype.forEach.call(el.querySelectorAll(".ap-mapa path"), function (p) {
