  // votos do candidato por cidade de MT + agregados por região do IBGE
  function porCidade(mapa, gmt, n) {
    var votos = (mapa.cand || {})[String(n)] || [], cidades = [], reg = {}, imd = {}, porCdi = {};
    (mapa.mun || []).forEach(function (m, j) {
      var v = votos[j] || 0, g = (gmt.mun || {})[m.cdi] || {};
      var x = {cd: m.cd, cdi: m.cdi, nm: m.nm, v: v, t: m.validos || 0, p: m.validos ? 100 * v / m.validos : 0,
        ri: g.ri || "—", rg: g.rg || "—", ap: m.apurado};
      // posição do candidato na cidade
      var acima = 0;
      Object.keys(mapa.cand).forEach(function (k) { if ((mapa.cand[k][j] || 0) > v) acima++; });
      x.pos = v ? acima + 1 : null;
      cidades.push(x);
      if (m.cdi) porCdi[m.cdi] = x;
      [[reg, x.rg], [imd, x.ri]].forEach(function (par) {
        var o = par[0][par[1]] || (par[0][par[1]] = {nm: par[1], v: 0, t: 0});
        o.v += v; o.t += x.t;
      });
    });
    function lista(o) {
      return Object.keys(o).map(function (k) { var r = o[k]; r.p = r.t ? 100 * r.v / r.t : 0; return r; })
        .sort(function (a, b) { return b.p - a.p; });
    }
    return {cidades: cidades, porCdi: porCdi, regioes: lista(reg), imediatas: lista(imd)};
  }
  function fmtVP(x) { return x.p.toFixed(2).replace(".", ",") + "% · " + num(x.v) + " votos"; }
  function secaoMT(c, cargo, mapa, gmt, rotuloLugar) {
    var r = porCidade(mapa, gmt, c.n);
    var top = r.cidades.slice().sort(function (a, b) { return b.v - a.v; });
    var forte = r.cidades.filter(function (x) { return x.t >= 500; }).sort(function (a, b) { return b.p - a.p; });
    var vence = r.cidades.filter(function (x) { return x.pos === 1; }).length;
    var html = '<section class="ap-f-sec" id="ap-f-mapa"><h3>Mapa de ' + esc(rotuloLugar) + "</h3>" +
