      '<div class="ap-f-dois"><div><h4 class="ap-mini">REGIÕES INTERMEDIÁRIAS</h4>' + barras(r.regioes, fmtVP) + "</div>" +
      '<div><h4 class="ap-mini">REGIÕES IMEDIATAS</h4>' + barras(r.imediatas, fmtVP) + "</div></div></section>" +
      '<section class="ap-f-sec" id="ap-f-cidades"><h3>Por cidade</h3>' +
      '<div class="ap-f-dois"><div><h4 class="ap-mini">ONDE TEVE MAIS VOTOS</h4>' + barras(top.slice(0, 10), function (x) {
        return num(x.v) + " votos";
      }) + "</div>" +
      '<div><h4 class="ap-mini">MAIOR PERCENTUAL (municípios com 500+ votos válidos)</h4>' + barras(forte.slice(0, 10)) + "</div></div>" +
      '<h4 class="ap-mini" style="margin-top:16px">TODOS OS ' + r.cidades.length + " MUNICÍPIOS</h4>" +
      tabela("ap-f-tcid", ["Município", "Votos", "%", "Posição"], top.map(function (x) {
        return "<tr><td>" + esc(x.nm) + '<div class="ap-mini">' + esc(x.ri) + "</div></td><td>" + num(x.v) + "</td><td>" +
          x.p.toFixed(2).replace(".", ",") + "%</td><td>" + (x.pos ? x.pos + "º" : "—") + "</td></tr>";
      })) + "</section>";
    return {html: html, itens: r.porCdi, chave: function (k) { return k; }};
