    var vence = ufs.filter(function (x) { return x.pos === 1 && x.cd !== "zz"; }).length;
    var html = '<section class="ap-f-sec" id="ap-f-mapa"><h3>Mapa do Brasil</h3>' +
      '<p class="ap-f-nota">Percentual de votos válidos do candidato em cada estado. Lidera em ' + vence + " de 27 unidades da federação.</p>" +
      '<div data-mapa="br"></div></section>' +
