      '<h4 class="ap-mini" style="margin-top:16px">TABELA</h4>' +
      tabela("ap-f-tuf", ["Estado", "Votos", "%", "Posição"], ufs.slice().sort(function (a, b) { return b.v - a.v; }).map(function (x) {
        return "<tr><td>" + esc(x.nm) + "</td><td>" + num(x.v) + "</td><td>" + x.p.toFixed(2).replace(".", ",") +
          "%</td><td>" + (x.pos ? x.pos + "º" : "—") + "</td></tr>";
