        return {nm: m.nm, v: v, t: m.validos || 0, p: m.validos ? 100 * v / m.validos : 0, pos: v ? acima + 1 : null};
      });
      var tv = cid.reduce(function (s, x) { return s + x.v; }, 0), tt = cid.reduce(function (s, x) { return s + x.t; }, 0);
      var vEx = cid.filter(function (x) { return x.pos === 1; }).length;
