        barras(top.slice(0, 10), function (x) { return num(x.v) + " votos"; }) + "</div>" +
        '<div><h4 class="ap-mini">MAIOR PERCENTUAL (cidades com 1.000+ votos válidos)</h4>' +
        barras(cid.filter(function (x) { return x.t >= 1000; }).sort(function (a, b) { return b.p - a.p; }).slice(0, 10)) +
        "</div></div>" +
        '<h4 class="ap-mini" style="margin-top:16px">TODAS AS CIDADES</h4>' +
        tabela("ap-f-text", ["Cidade", "Votos", "%", "Posição"], top.map(function (x) {
          return "<tr><td>" + esc(x.nm) + "</td><td>" + num(x.v) + "</td><td>" + x.p.toFixed(2).replace(".", ",") +
            "%</td><td>" + (x.pos ? x.pos + "º" : "—") + "</td></tr>";
        })) + "</section>";
    }
    return {html: html, itens: itens, chave: function (k) { return k; }};
  }

  // ---------- dados do DivulgaCand (Portal de Dados Abertos do TSE) ----------
  var TSE = {};
  function arquivoTse(cargo, uf, n) {
    return uf + "-c" + cargo + (/^000[678]$/.test(cargo) ? "-" + ((parseInt(n, 10) || 0) % 8) : "") + ".json";
  }
  function pegaTse(nome) {
    if (TSE[nome]) return Promise.resolve(TSE[nome]);
    return fetch("/content/media/apuracao/cand/" + nome + "?t=" + Math.floor(Date.now() / 600000))
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) { if (d) TSE[nome] = d; return d; }).catch(function () { return null; });
  }
  function cap(t) {
    return String(t || "").toLowerCase().replace(/(^|[\s(\/-])([a-zà-ú])/g, function (m, a, b) { return a + b.toUpperCase(); })
      .replace(/\b(De|Da|Do|Das|Dos|E|Em|Com|Ou|Por|Para|A|O)\b/g, function (m) { return m.toLowerCase(); });
  }
  function dataBr(x) {
    var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(x || "");
    return m ? m[3] + "/" + m[2] + "/" + m[1] : (x || "");
  }
  function instancia(inst, trib) {
    if (inst === "3" || trib === "BR") return "TSE";
    if (inst === "2") return "TRE-" + (trib || "");
    return "Juízo eleitoral" + (trib ? " (" + trib + ")" : "");
  }
  function itemDl(rot, val) { return val ? "<div><dt>" + rot + "</dt><dd>" + esc(val) + "</dd></div>" : ""; }
  function renderTse(t, d) {
    var aberto = t.aberto, st = t.situacao || t.julgamento || "Sem informação";
    var classe = aberto ? "aberto" : /^DEFERIDO$/i.test(st) ? "ok" : "";
    var h = '<h3>Candidatura no TSE</h3><div class="ap-tse-st"><span class="ap-pill ' + classe + '">' + esc(cap(st)) + "</span>" +
      (t.destino_votos ? '<span class="ap-mini">Votos: ' + esc(t.destino_votos) + "</span>" : "") + "</div>";
    if (aberto) h += '<div class="ap-f-aviso"><strong>Julgamento ainda não encerrado.</strong> A situação acima é a informada pelo TSE ' +
      "e pode mudar com o recurso. Esta ficha é atualizada com os dados oficiais até a decisão final.</div>";
    h += '<dl class="ap-dl">' +
      itemDl("Situação da candidatura", t.situacao && cap(t.situacao)) +
      itemDl("Julgamento do registro", t.julgamento && cap(t.julgamento)) +
      itemDl("Situação para o pleito", t.julgamento_pleito && cap(t.julgamento_pleito)) +
      itemDl("Situação na urna", t.julgamento_urna && cap(t.julgamento_urna)) +
      itemDl("Cassação", t.cassacao && cap(t.cassacao)) +
      itemDl("Diplomação", t.diploma && cap(t.diploma)) +
      itemDl("Processo de registro", t.processo) +
      itemDl("Pedido de registro aceito em", t.aceite && dataBr(t.aceite)) +
      itemDl("Candidatura de substituição", t.substituto ? "Sim" : "") +
      itemDl("Limite de gastos de campanha", t.limite_gastos && moeda(t.limite_gastos)) + "</dl>";
    if (t.motivos && t.motivos.length) h += '<h4 class="ap-mini">FUNDAMENTOS INFORMADOS PELO TSE</h4><ul class="ap-f-nota">' +
      t.motivos.map(function (m) { return "<li>" + esc(m) + "</li>"; }).join("") + "</ul>";
    var tl = (t.decisoes || []).map(function (x) {
      return {k: x[0], h: "<b>" + esc(x[0]) + "</b> · " + esc(x[1] || "Decisão") + " · " + esc(instancia(x[3], x[4])) +
        (x[2] ? '<div class="ap-mini">' + esc(cap(x[2])) + "</div>" : "")};
    }).concat((t.recursos || []).map(function (x) {
      return {k: x.autuacao, h: "<b>" + esc(x.autuacao || "") + "</b> · " + esc(cap(x.classe || x.tipo || "Recurso")) + " autuado no " +
        esc(instancia(x.inst, x.trib)) + '<div class="ap-mini">' + (x.relator ? "Relator: " + esc(cap(x.relator)) : "") +
        (x.baixa ? " · baixa em " + esc(x.baixa) : " · em tramitação") +
        (x.ultima && x.ultima !== "Não informado" ? " · última decisão: " + esc(x.ultima) + (x.data_ultima ? " (" + esc(x.data_ultima) + ")" : "") : "") +
        "</div>"};
    })).sort(function (a, b) {
      var f = function (s) { s = s || ""; return s.slice(6, 10) + s.slice(3, 5) + s.slice(0, 2); };
      return f(a.k) < f(b.k) ? -1 : 1;
    });
    if (tl.length) h += '<h4 class="ap-mini">ANDAMENTO DO PROCESSO DE REGISTRO</h4><ol class="ap-tl">' +
      tl.map(function (x) { return "<li>" + x.h + "</li>"; }).join("") + "</ol>";
    h += '<h4 class="ap-mini">PERFIL</h4><dl class="ap-dl">' +
      itemDl("Nome completo", t.nc) + itemDl("Nome social", t.ns) +
      itemDl("Idade na posse", t.idade_posse && t.idade_posse + " anos") +
      itemDl("Naturalidade", [t.mun_nasc && cap(t.mun_nasc), t.uf_nasc].filter(Boolean).join(" / ")) +
      itemDl("Nacionalidade", t.nacionalidade && cap(t.nacionalidade)) +
      itemDl("Gênero", t.genero && cap(t.genero)) + itemDl("Cor/raça", t.cor_raca && cap(t.cor_raca)) +
      itemDl("Grau de instrução", t.instrucao && cap(t.instrucao)) + itemDl("Estado civil", t.estado_civil && cap(t.estado_civil)) +
      itemDl("Ocupação declarada", t.ocupacao && cap(t.ocupacao)) +
      itemDl("Quilombola", t.quilombola ? "Sim" : "") + itemDl("Etnia indígena", t.etnia && cap(t.etnia)) + "</dl>";
    var p = t.partido || {};
    h += '<h4 class="ap-mini">PARTIDO E ALIANÇA</h4><dl class="ap-dl">' +
      itemDl("Partido", [p.n, p.sg, p.nm && p.nm !== p.sg ? "— " + cap(p.nm) : ""].filter(Boolean).join(" ")) +
      itemDl("Federação", t.federacao) +
      itemDl(t.tp_agremiacao === "COLIGAÇÃO" ? "Coligação" : "Agremiação", t.coligacao && t.coligacao !== p.sg ? t.coligacao : "") +
      itemDl("Composição", t.composicao) + "</dl>";
    if (t.bens_qtd) {
      var tipos = {};
      (t.bens || []).forEach(function (b) { tipos[b[0]] = (tipos[b[0]] || 0) + b[2]; });
      var lt = Object.keys(tipos).map(function (k) { return {nm: k, p: tipos[k]}; }).sort(function (a, b) { return b.p - a.p; });
      h += '<h4 class="ap-mini">BENS DECLARADOS</h4><p class="ap-f-nota"><strong>' + moeda(t.bens_total) + "</strong> em " + t.bens_qtd +
        (t.bens_qtd === 1 ? " bem" : " bens") + ", valores informados pelo próprio candidato à Justiça Eleitoral" +
        (t.bens_qtd > (t.bens || []).length ? " (a lista abaixo mostra os " + t.bens.length + " de maior valor)" : "") + ".</p>" +
        barras(lt.slice(0, 8), function (x) { return moeda(x.p); }) +
        '<div style="margin-top:12px">' + tabela("ap-f-tbens", ["Bem", "Valor"], (t.bens || []).map(function (b) {
          return "<tr><td>" + esc(b[1] || b[0]) + '<div class="ap-mini">' + esc(b[0]) + "</div></td><td>" + moeda(b[2]) + "</td></tr>";
        })) + "</div>";
    } else {
      h += '<h4 class="ap-mini">BENS DECLARADOS</h4><p class="ap-f-nota">Nenhum bem declarado à Justiça Eleitoral.</p>';
    }
    if (t.redes && t.redes.length) h += '<h4 class="ap-mini">REDES INFORMADAS AO TSE</h4><div class="ap-redes">' +
      t.redes.map(function (u) {
        return '<a href="' + esc(u) + '" target="_blank" rel="nofollow noopener noreferrer">' +
          esc(u.replace(/^https?:\/\/(www\.)?/, "")) + "</a>";
      }).join("") + "</div>";
    if (t.historico && t.historico.length) h += '<h4 class="ap-mini">CANDIDATURAS ANTERIORES</h4>' +
      '<div class="ap-f-tab"><table><thead><tr><th>Ano</th><th>Cargo</th><th>Local</th><th>Partido</th><th>Resultado</th></tr></thead><tbody>' +
      t.historico.map(function (x) {
        return "<tr><td>" + esc(x[0]) + "</td><td>" + esc(x[1]) + "</td><td>" + esc(cap(x[2])) + "</td><td>" + esc(x[3] || "") +
          "</td><td>" + esc(x[6] || x[5] || "—") + "</td></tr>";
      }).join("") + "</tbody></table></div>";
    h += '<p class="ap-fonte">Fonte: TSE, Portal de Dados Abertos (os mesmos dados do DivulgaCand), arquivo de ' + esc(d.gerado || "") +
      ". CPF, título de eleitor e e-mail não são exibidos.</p>";
    return h;
  }
  function carregaTse(c, cargo, uf, meu) {
    var sq = (/(\d+)\.jpeg$/.exec(c.foto || "") || [])[1];
    pegaTse(arquivoTse(cargo, uf, c.n)).then(function (d) {
      if (meu !== fichaPedido) return;
      var el = document.getElementById("ap-f-tse");
      if (!el) return;
      var t = d && ((sq && d.c[sq]) || d.c[(d.idx || {})[String(c.n)]]);
      if (!t) { el.innerHTML = '<h3>Candidatura no TSE</h3><p class="ap-f-nota">Os dados do registro deste candidato ainda não ' +
        "foram publicados pelo TSE.</p>"; return; }
      el.innerHTML = renderTse(t, d);
      ligarBuscas(el);
    });
  }
  function fechaFicha(semHistorico) {
    var f = $("ap-ficha");
    if (f.hidden) return;
    f.hidden = true; fichaAberta = ""; ++fichaPedido;
    document.documentElement.style.overflow = "";
    if (!semHistorico && /^#ficha=/.test(location.hash)) history.back();
    if (fichaFoco && fichaFoco.focus) fichaFoco.focus();
  }
  function abreFicha(chave, empilha) {
    var partes = String(chave).split("|"), cargo = partes[0], uf = partes[1], n = partes[2];
    if (!cargo || !uf || !n) return;
    if (cargo === "0001") uf = "br";
    var f = $("ap-ficha"), corpo = $("ap-f-corpo"), meu = ++fichaPedido;
    if (empilha !== false && location.hash !== "#ficha=" + chave) history.pushState({ficha: chave}, "", "#ficha=" + chave);
    fichaAberta = chave;
    corpo.innerHTML = '<div class="ap-aviso"><b>Carregando a ficha…</b></div>';
    f.hidden = false;
    document.documentElement.style.overflow = "hidden";
    f.querySelector(".ap-f-caixa").focus();
    var naMt = uf === "mt" || cargo === "0001";
    Promise.all([
      pega(uf + "-c" + cargo + ".json"),
      cargo === "0001" ? pega("mapa-br-c0001.json") : null,
      cargo === "0001" ? geo("geo-br") : null,
      cargo === "0001" ? pega("exterior-c0001.json") : null,
      naMt ? pega("mapa-mt-c" + cargo + ".json") : null,
      naMt ? geo("geo-mt") : null,
      cargo === "0001" ? pega("mt-c0001.json") : null
    ]).then(function (r) {
      if (meu !== fichaPedido) return;
      var d = r[0], c = d && (d.candidatos || []).filter(function (x) { return String(x.n) === String(n); })[0];
      if (!c) { corpo.innerHTML = '<div class="ap-aviso"><b>Candidato não encontrado</b>Os dados podem ter sido atualizados. Feche e tente de novo.</div>'; return; }
      var todos = d.candidatos || [], pos = todos.indexOf(c) + 1;
      var vv = parseInt(d.votos_validos_c || d.votos_validos, 10) || 0;
      var lugar = uf === "br" ? "Brasil" : (UFS[uf] || uf.toUpperCase());
      var html = '<div class="ap-f-topo">' + avatar(c) + '<div style="min-width:0"><div class="ap-mini">' +
        esc((CARGO_NOME[cargo] || "") + " · " + lugar) + "</div>" +
        '<h2 id="ap-f-nome">' + esc(c.nm || "") + " " + selo(c) + "</h2>" +
        '<div class="ap-f-sub">Nº ' + esc(c.n) + " · " + esc(c.cc || siglaDe(c)) +
        (c.ag && c.cc && c.cc.indexOf(c.ag) === -1 && c.ag !== siglaDe(c) ? "<br>Coligação: " + esc(c.ag) : "") +
        (c.nv ? "<br>Vice: " + esc(c.nv) : "") + (c.sp ? "<br>Suplentes: " + esc(c.sp) : "") +
        (c.st ? "<br>Situação no TSE: " + esc(c.st) : "") + (c.dvt ? " · " + esc(c.dvt) : "") + "</div></div></div>" +
        '<div class="ap-f-kpis">' +
        '<div class="ap-f-kpi"><b>' + num(c.vap) + "</b><span>votos</span></div>" +
        '<div class="ap-f-kpi"><b>' + esc(c.pvap || "0") + "%</b><span>dos válidos</span></div>" +
        '<div class="ap-f-kpi"><b>' + pos + "º</b><span>de " + todos.length + " candidatos</span></div>" +
        '<div class="ap-f-kpi"><b>' + esc(d.secoes_totalizadas_pct || "0") + "%</b><span>das seções apuradas</span></div></div>";
      var extra = null, extraMt = null;
      if (cargo === "0001" && r[1] && r[2]) extra = secaoPresidente(c, r[1], r[2], r[3]);
      if (naMt && r[4] && r[5]) {
        var cm = c;
        if (cargo === "0001") {
          var dm = r[6], achou = dm && (dm.candidatos || []).filter(function (x) { return String(x.n) === String(n); })[0];
          if (achou) cm = achou;
        }
        extraMt = secaoMT(cm, cargo, r[4], r[5], "Mato Grosso");
      }
      var nav = [];
      if (extra) nav.push(["ap-f-mapa", "Mapa"], ["ap-f-estados", "Estados"]);
      if (extra && r[3]) nav.push(["ap-f-exterior", "Exterior"]);
      if (extraMt) nav.push([extra ? "ap-f-mt" : "ap-f-mapa", extra ? "Mato Grosso" : "Mapa"], ["ap-f-regioes", "Regiões"], ["ap-f-cidades", "Cidades"]);
      nav.splice(nav.length && nav[0][0] === "ap-f-mapa" ? 1 : 0, 0, ["ap-f-tse", "Candidatura"]);
      nav.push(["ap-f-locais", "Bairros e distritos"]);
      html += '<nav class="ap-f-nav" aria-label="Seções da ficha">' + nav.map(function (x) {
        return '<a href="#' + x[0] + '" data-ir="' + x[0] + '">' + x[1] + "</a>";
      }).join("") + "</nav>";
      var slot = '<section class="ap-f-sec" id="ap-f-tse"><h3>Candidatura no TSE</h3>' +
        '<p class="ap-f-nota">Carregando os dados do registro…</p></section>';
      var antes = html.length;
      if (extra) html += extra.html;
      if (extraMt) {
        var mtHtml = extraMt.html;
        if (extra) mtHtml = '<section class="ap-f-sec" id="ap-f-mt"><h3>Em Mato Grosso</h3><p class="ap-f-nota">' +
          num(cm.vap) + " votos em MT (" + esc(cm.pvap || "0") + "% dos válidos do estado).</p></section>" +
          mtHtml.replace('id="ap-f-mapa"', "");
        html += mtHtml;
      }
      // dados do DivulgaCand logo depois do primeiro gráfico (pedido do Hebert)
      var fim = html.indexOf("</section>", antes);
      html = fim === -1 ? html + slot : html.slice(0, fim + 10) + slot + html.slice(fim + 10);
      if (!extra && !extraMt) html += '<section class="ap-f-sec"><h3>Por região e por cidade</h3><p class="ap-f-nota">' +
        "O detalhamento por região, município e mapa está disponível para os candidatos de Mato Grosso e para Presidente." +
        " Para os demais estados, a página mostra o total oficial do TSE.</p></section>";
      html += '<section class="ap-f-sec" id="ap-f-locais"><h3>Bairros, distritos e locais de votação</h3><p class="ap-f-nota">' +
        "O TSE divulga o resultado por município. O voto por bairro, distrito e comunidade rural depende dos boletins " +
        "de urna de cada seção e do cadastro dos locais de votação; esse recorte entra aqui assim que for processado.</p></section>" +
        '<p class="ap-fonte">Fonte: TSE (resultados de ' + esc(d.atualizado || "") + "). Regiões e mapas: IBGE.</p>";
      corpo.innerHTML = html;
      if (extra) {
        corpo.querySelector('[data-mapa="br"]').innerHTML = mapaSvg(r[2], function (k) { return k; }, extra.itens, "Mapa do Brasil por estado");
        ligarMapa(corpo.querySelector('[data-mapa="br"]'), extra.itens, fmtVP);
      }
      if (extraMt) {
        corpo.querySelector('[data-mapa="mt"]').innerHTML = mapaSvg(r[5], function (k) { return k; }, extraMt.itens, "Mapa de Mato Grosso por município");
        ligarMapa(corpo.querySelector('[data-mapa="mt"]'), extraMt.itens, fmtVP);
      }
      ligarBuscas(corpo);
      carregaTse(c, cargo, uf, meu);
      Array.prototype.forEach.call(corpo.querySelectorAll("[data-ir]"), function (a) {
        a.onclick = function (ev) {
          ev.preventDefault();
          var alvo = document.getElementById(a.dataset.ir);
          if (alvo) alvo.scrollIntoView({block: "start"});
        };
      });
    });
  }
  (function ligarFicha() {
    var f = $("ap-ficha");
    document.body.appendChild(f);    // fora do conteúdo do post: nenhum transform/overflow do tema prende o painel
    f.querySelector(".ap-f-fechar").onclick = function () { fechaFicha(); };
    f.addEventListener("click", function (ev) { if (ev.target === f) fechaFicha(); });
    document.addEventListener("keydown", function (ev) { if (ev.key === "Escape" && !f.hidden) fechaFicha(); });
    function alvoCard(ev) { var t = ev.target; return t && t.closest ? t.closest("[data-ficha]") : null; }
    $("hmt-apuracao").addEventListener("click", function (ev) {
      var card = alvoCard(ev);
      if (!card || ev.target.closest("button,a,select,input")) return;
      fichaFoco = card; abreFicha(card.dataset.ficha);
    });
    $("hmt-apuracao").addEventListener("keydown", function (ev) {
      var card = alvoCard(ev);
      if (card && (ev.key === "Enter" || ev.key === " ")) { ev.preventDefault(); fichaFoco = card; abreFicha(card.dataset.ficha); }
    });
    window.addEventListener("popstate", function () {
      var m = /^#ficha=(.+)$/.exec(location.hash);
      if (m) abreFicha(decodeURIComponent(m[1]), false); else fechaFicha(true);
    });
    var m = /^#ficha=(.+)$/.exec(location.hash);
    if (m) abreFicha(decodeURIComponent(m[1]), false);
  })();
  ciclo();
  setInterval(ciclo, 30000);   // o coletor renova os dados 2 vezes por minuto
})();
</script>
